# Postępowanie administracyjne (KPA) i samorząd gminny.
SEG = "ADM"
CAT = "plapAdministracyjne"
Q = [
    ("Kto jest stroną w postępowaniu administracyjnym?",
     "Każdy, czyjego interesu prawnego ono dotyczy", ["Każdy, kto ma interes faktyczny", "Wyłącznie wnioskodawca", "Każdy mieszkaniec danej gminy"],
     "Art. 28 KPA: stroną jest każdy, czyjego interesu prawnego lub obowiązku dotyczy postępowanie albo kto żąda czynności organu ze względu na swój interes prawny lub obowiązek. Interes faktyczny nie wystarcza."),
    ("Jak nazywa się zasada, według której przed decyzją strona może wypowiedzieć się co do zebranych dowodów?",
     "Czynnego udziału strony", ["Prawdy obiektywnej", "Dwuinstancyjności", "Trwałości decyzji"],
     "Art. 10 § 1 KPA: organy zapewniają stronom czynny udział w każdym stadium postępowania i przed wydaniem decyzji umożliwiają wypowiedzenie się co do dowodów, materiałów i żądań."),
    ("W jakim terminie organ powinien załatwić sprawę szczególnie skomplikowaną?",
     "2 miesięcy od wszczęcia", ["Miesiąca od wszczęcia", "3 miesięcy od wszczęcia", "14 dni od wszczęcia"],
     "Art. 35 § 3 KPA: sprawę wymagającą postępowania wyjaśniającego załatwia się nie później niż w ciągu miesiąca, a szczególnie skomplikowaną w ciągu dwóch miesięcy od wszczęcia."),
    ("Jaki środek przysługuje stronie na bezczynność organu administracji?",
     "Ponaglenie", ["Zażalenie", "Odwołanie", "Wniosek o wznowienie"],
     "Art. 37 § 1 KPA: stronie służy ponaglenie na bezczynność i przewlekłość. Wnosi się je do organu wyższego stopnia za pośrednictwem organu prowadzącego postępowanie (§ 3)."),
    ("W jakim terminie wnosi się prośbę o przywrócenie terminu w postępowaniu administracyjnym?",
     "7 dni od ustania przyczyny", ["14 dni od ustania przyczyny", "7 dni od uchybienia terminu", "30 dni od ustania przyczyny"],
     "Art. 58 § 2 KPA: prośbę wnosi się w ciągu siedmiu dni od dnia ustania przyczyny uchybienia i jednocześnie dopełnia się czynności. Przywrócenie terminu do złożenia prośby jest niedopuszczalne (§ 3)."),
    ("Co wydaje organ, gdy żądanie wszczęcia postępowania wniosła osoba niebędąca stroną?",
     "Postanowienie o odmowie wszczęcia", ["Decyzję o umorzeniu postępowania", "Decyzję odmowną co do istoty", "Pismo o pozostawieniu bez biegu"],
     "Art. 61a § 1 KPA: organ wydaje postanowienie o odmowie wszczęcia postępowania, na które służy zażalenie (§ 2)."),
    ("Co przysługuje od decyzji ministra wydanej w pierwszej instancji?",
     "Wniosek o ponowne rozpatrzenie", ["Odwołanie do Prezesa Rady Ministrów", "Zażalenie do kolegium odwoławczego", "Odwołanie do wojewody"],
     "Art. 127 § 3 KPA: od decyzji wydanej w pierwszej instancji przez ministra lub samorządowe kolegium odwoławcze nie służy odwołanie; strona może zwrócić się z wnioskiem o ponowne rozpatrzenie sprawy."),
    ("Jaki skutek ma zrzeczenie się prawa do odwołania przez ostatnią ze stron?",
     "Decyzja staje się ostateczna i prawomocna", ["Decyzja wygasa z mocy prawa", "Organ musi ponownie rozpatrzyć sprawę", "Termin odwołania biegnie od nowa"],
     "Art. 127a § 2 KPA: z dniem doręczenia organowi oświadczenia o zrzeczeniu się odwołania przez ostatnią ze stron decyzja staje się ostateczna i prawomocna."),
    ("Ile co do zasady wynosi termin do wniesienia odwołania od decyzji?",
     "14 dni", ["7 dni", "30 dni", "21 dni"],
     "Art. 129 § 2 KPA: odwołanie wnosi się w terminie czternastu dni od doręczenia decyzji, a przy decyzji ogłoszonej ustnie od jej ogłoszenia; przepisy szczególne mogą przewidywać inne terminy (§ 3)."),
    ("Za pośrednictwem jakiego organu wnosi się odwołanie od decyzji?",
     "Organu, który wydał decyzję", ["Organu wyższego stopnia", "Wojewódzkiego sądu administracyjnego", "Rzecznika Praw Obywatelskich"],
     "Art. 129 § 1 KPA: odwołanie wnosi się do organu odwoławczego za pośrednictwem organu, który wydał decyzję."),
    ("Z jakiego powodu organ odwoławczy może uchylić decyzję i przekazać sprawę do ponownego rozpatrzenia?",
     "Naruszenia przepisów postępowania", ["Naruszenia prawa materialnego", "Nieuiszczenia opłaty skarbowej", "Zmiany przepisów po wydaniu decyzji"],
     "Art. 138 § 2 KPA: organ odwoławczy może uchylić decyzję w całości i przekazać sprawę, gdy wydano ją z naruszeniem przepisów postępowania, a konieczny do wyjaśnienia zakres sprawy ma istotny wpływ na rozstrzygnięcie."),
    ("Która przesłanka uzasadnia wznowienie postępowania administracyjnego?",
     "Decyzja wydana w wyniku przestępstwa", ["Decyzja wydana bez podstawy prawnej", "Rażące naruszenie prawa w decyzji", "Decyzja skierowana do osoby niebędącej stroną"],
     "Art. 145 § 1 pkt 2 KPA: postępowanie wznawia się, gdy decyzja została wydana w wyniku przestępstwa. Brak podstawy prawnej, rażące naruszenie prawa i skierowanie do nie-strony to przesłanki nieważności (art. 156 § 1 KPA)."),
    ("Po ilu latach od doręczenia decyzji nie stwierdza się już jej nieważności z powodu rażącego naruszenia prawa?",
     "10 lat", ["3 lata", "5 lat", "7 lat"],
     "Art. 156 § 2 KPA: nie stwierdza się nieważności z przyczyn z § 1, jeżeli od doręczenia lub ogłoszenia decyzji upłynęło dziesięć lat, a także gdy decyzja wywołała nieodwracalne skutki prawne."),
    ("Kiedy organ może odstąpić od utrwalonej praktyki rozstrzygania spraw w takim samym stanie faktycznym i prawnym?",
     "Z uzasadnionej przyczyny", ["Na każdy wniosek strony", "Za zgodą organu wyższego stopnia", "Wyłącznie po zmianie ustawy"],
     "Art. 8 § 2 KPA: organy bez uzasadnionej przyczyny nie odstępują od utrwalonej praktyki rozstrzygania spraw w takim samym stanie faktycznym i prawnym."),
    ("W jakiej formie organ co do zasady załatwia sprawę w postępowaniu administracyjnym?",
     "Decyzji", ["Postanowienia", "Zaświadczenia", "Notatki służbowej"],
     "Art. 104 § 1 KPA: organ załatwia sprawę przez wydanie decyzji, chyba że przepisy kodeksu stanowią inaczej. Postanowienia rozstrzygają kwestie wynikające w toku postępowania."),
    ("Jakie są organy gminy według ustawy o samorządzie gminnym?",
     "Rada gminy i wójt", ["Rada gminy i starosta", "Wójt i sołtys", "Rada gminy i wojewoda"],
     "Art. 11a ust. 1 ustawy o samorządzie gminnym: organami gminy są rada gminy oraz wójt (burmistrz, prezydent miasta). Rada jest organem stanowiącym i kontrolnym (art. 15 ust. 1)."),
]
